script:
(() => {
  const arm = () => {
    const html = document.documentElement;
    html.classList.add("pr-js");

    document.querySelectorAll(".pr-tabs").forEach((tabs) => {
      const buttons = Array.from(tabs.querySelectorAll(".pr-tab"));
      const scope = tabs.closest(".pr-tabwrap") || document;
      const panes = Array.from(scope.querySelectorAll(".pr-tabpanel"));
      const select = (index) => {
        buttons.forEach((btn, i) =>
          btn.setAttribute("aria-selected", i === index ? "true" : "false"));
        panes.forEach((pane, i) => pane.classList.toggle("pr-active", i === index));
      };
      buttons.forEach((btn, i) => btn.addEventListener("click", () => select(i)));
      select(0);
    });

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    html.classList.add("pr-motion");
    const io = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        entry.target.classList.add("pr-in");
        io.unobserve(entry.target);
      }
    }, { threshold: 0.08, rootMargin: "0px 0px -6% 0px" });
    document.querySelectorAll(".pr-rise").forEach((el) => io.observe(el));
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", arm);
  } else {
    arm();
  }
})();
